/* 2389 Research Night Shift. The engine, FM timing signals and track sounds are
   synthesized locally, and the first driver interaction opens the device. */
import { MTMKit } from './kit.js';

const MTMAudio = (() => {
  'use strict';

  const {clamp} = MTMKit;
  const bases = [950, 2700, 5600];
  // The lab identification signal uses semitone offsets 2, 3, 8 and 9 over D4.
  const ident = [2, 3, 8, 9].map(semitones => 293.6648 * 2 ** (semitones / 12));
  // Each truck has two differently tuned pneumatic bells, in garage order.
  const truckHorns = [
    {bells: [220, 330], cutoff: 1780, duration: 0.29}, // BIGFOOT, open fifth
    {bells: [156, 185], cutoff: 1420, duration: 0.34}, // Grave Digger, low minor third
    {bells: [311, 349], cutoff: 2210, duration: 0.22}, // Snake Bite, close-pitched reeds
    {bells: [262, 349], cutoff: 1950, duration: 0.26}  // Carolina Crusher, bright fourth
  ];
  const longCues = new Set(['horn', 'quack', 'bell', 'bleep', 'steam', 'cheer', 'brass', 'copier', 'coin', 'launchPerfect', 'launchBog']);
  // The same contact force can sound like a tire groan, a panel squeal or a
  // broad stone rasp. Each surface has a noise band and a quieter resonance.
  const contactMaterials = new Map([
    ['rubber',  {band: 420,  q: 1.8, noise: 0.21, pitch: 175, ring: 0.055}],
    ['metal',   {band: 1930, q: 1.6, noise: 0.25, pitch: 794, ring: 0.032}],
    ['wood',    {band: 590,  q: 0.8, noise: 0.21, pitch: 118, ring: 0.016}],
    ['plastic', {band: 1120, q: 2.2, noise: 0.23, pitch: 385, ring: 0.032}],
    ['stone',   {band: 1350, q: 0.55, noise: 0.22, pitch: 92, ring: 0.006}]
  ]);
  const lastTarget = new WeakMap();
  const recentEffects = new Map();
  const oneShots = new Set();
  let audio = null;
  let muted = false;
  let active = false;
  let lastMix = -1;
  let idleTimer = 0;
  let duckUntil = 0;
  let spoken = null;
  let audience = null;
  let audienceArmed = false;
  let marshalUntil = 0;
  let rngState = 0x44a10d29;

  function random() {
    rngState = (Math.imul(rngState, 1664525) + 1013904223) >>> 0;
    return rngState / 4294967296;
  }

  function gain(ctx, amount, output) {
    const node = ctx.createGain();
    node.gain.value = amount;
    node.connect(output);
    return node;
  }

  function filter(ctx, type, frequency, q, output) {
    const node = ctx.createBiquadFilter();
    node.type = type;
    node.frequency.value = frequency;
    node.Q.value = q;
    node.connect(output);
    return node;
  }

  // Re-use the same parameter trajectories between frames at constant load.
  function target(param, value, time, tau = 0.045) {
    if (lastTarget.get(param) === value) return;
    param.setTargetAtTime(value, time, tau);
    lastTarget.set(param, value);
  }

  // A four-stroke V8 fires eight times every two revolutions. Give each
  // exhaust bank its uneven series of pulses and its own microphone distance.
  function exhaustSample(ctx, baseRpm) {
    const rate = 24000;
    const cycles = 8;
    const slots = cycles * 8;
    const frames = Math.round(rate * 120 / baseRpm * cycles);
    const sound = ctx.createBuffer(2, frames, rate);
    const channels = [sound.getChannelData(0), sound.getChannelData(1)];
    const bankOrder = [0, 1, 1, 0, 1, 0, 0, 1];
    const cylinderPower = [1.00, 0.85, 0.94, 1.03, 0.83, 0.98, 0.87, 1.04];
    const load = baseRpm / 7000;
    const ringLength = Math.round(rate * (0.065 - 0.015 * load));

    for (let fire = 0; fire < slots; fire++) {
      const cylinder = fire % 8;
      const bank = bankOrder[cylinder];
      const origin = Math.round(fire * frames / slots + (random() - 0.5) * 0.027 * frames / slots);
      const strength = cylinderPower[cylinder] * (0.87 + random() * 0.20);
      const tone = (bank ? 91 : 76) + load * 26;
      let turbulence = 0;
      for (let j = 0; j < ringLength; j++) {
        const t = j / rate;
        const hitEnvelope = (1 - Math.exp(-t * 1340)) * Math.exp(-t * (107 + 30 * load));
        const thump = Math.sin(2 * Math.PI * (tone * t + 0.19 * (1 - Math.exp(-t * 180))));
        const rasp = Math.sin(2 * Math.PI * (227 + bank * 32 + load * 25) * t + 0.3);
        const snap = Math.sin(2 * Math.PI * (485 + bank * 75) * t + 0.8);
        turbulence += ((random() * 2 - 1) - turbulence) * 0.32;
        const impulse = strength * (
          (1 - Math.exp(-t * 730)) * Math.exp(-t * 72) * thump * 0.72 +
          hitEnvelope * (rasp * 0.32 + snap * 0.11 + turbulence * (0.9 + load))
        );
        const near = (origin + j + frames) % frames;
        const far = (near + 6) % frames;
        channels[bank][near] += impulse;
        channels[1 - bank][far] += impulse * 0.66;
      }
    }

    for (const channel of channels) {
      for (let n = 0; n < frames; n++) channel[n] = Math.tanh(channel[n] * 1.40);
    }
    return sound;
  }

  function audioGraph(ctx) {
    const compressor = ctx.createDynamicsCompressor();
    compressor.threshold.value = -13;
    compressor.knee.value = 13;
    compressor.ratio.value = 4;
    compressor.attack.value = 0.004;
    compressor.release.value = 0.16;
    compressor.connect(ctx.destination);
    const master = gain(ctx, muted ? 0 : 0.80, compressor);
    const engineBus = gain(ctx, 0, master);
    const exhaust = filter(ctx, 'lowpass', 850, 0.58, engineBus);
    const layers = bases.map(baseRpm => {
      const volume = gain(ctx, 0, exhaust);
      const source = ctx.createBufferSource();
      source.buffer = exhaustSample(ctx, baseRpm);
      source.loop = true;
      source.connect(volume);
      source.start();
      return {source, volume};
    });

    // Gear-mesh whine and the shaft fundamental rise under throttle. Both go
    // through the motor bus so coasting, radio ducking and pause cover them.
    const driveGain = gain(ctx, 0, engineBus);
    const gearTone = ctx.createOscillator();
    gearTone.type = 'triangle';
    gearTone.frequency.value = 200;
    gearTone.connect(driveGain);
    gearTone.start();
    const shaftGain = gain(ctx, 0, engineBus);
    const shaftTone = ctx.createOscillator();
    shaftTone.type = 'sine';
    shaftTone.frequency.value = 43;
    shaftTone.connect(shaftGain);
    shaftTone.start();

    // Re-use one precomputed noise bed for intake, tire scrub and dirt impacts.
    const noiseBuffer = ctx.createBuffer(1, 65536, 24000);
    const noise = noiseBuffer.getChannelData(0);
    for (let i = 0; i < noise.length; i++) noise[i] = random() * 2 - 1;
    const grit = ctx.createBufferSource();
    grit.buffer = noiseBuffer;
    grit.loop = true;
    const intakeVolume = gain(ctx, 0, engineBus);
    const intakeFilter = filter(ctx, 'bandpass', 550, 0.65, intakeVolume);
    grit.connect(intakeFilter);
    const groundVolume = gain(ctx, 0, engineBus);
    const groundFilter = filter(ctx, 'lowpass', 430, 0.65, groundVolume);
    grit.connect(groundFilter);
    const slipVolume = gain(ctx, 0, engineBus);
    const slipFilter = filter(ctx, 'bandpass', 950, 1.75, slipVolume);
    grit.connect(slipFilter);

    // A stationary burnout has little road noise. Pair a narrow rubber hiss
    // with a quiet stick-slip tone and run both through the same tire envelope.
    const spinGain = gain(ctx, 0, engineBus);
    const spinBand = filter(ctx, 'bandpass', 950, 2.7, spinGain);
    grit.connect(spinBand);
    const spinTone = ctx.createOscillator();
    spinTone.type = 'triangle';
    spinTone.frequency.value = 620;
    spinTone.connect(gain(ctx, 0.15, spinGain));
    spinTone.start();

    // Sustained rubbing needs a continuous envelope; a stream of collision
    // one-shots would chatter as adjacent wheel and chassis contacts trade off.
    const scrapeGain = gain(ctx, 0, engineBus);
    const scrapeFilter = filter(ctx, 'bandpass', 750, 1, scrapeGain);
    grit.connect(scrapeFilter);
    const scrapeRingGain = gain(ctx, 0, engineBus);
    const scrapeRing = ctx.createOscillator();
    scrapeRing.type = 'triangle';
    scrapeRing.frequency.value = 180;
    scrapeRing.connect(scrapeRingGain);
    scrapeRing.start();
    grit.start();

    return {ctx, master, engineBus, exhaust, layers, driveGain, gearTone, shaftGain, shaftTone, noiseBuffer, grit,
      intakeVolume, intakeFilter, groundVolume, groundFilter, slipVolume, slipFilter,
      spinGain, spinBand, spinTone, scrapeGain, scrapeFilter, scrapeRingGain, scrapeRing};
  }

  function wake() {
    clearTimeout(idleTimer);
    if (!audio || muted) return;
    if (audio.ctx.state === 'suspended' || audio.ctx.state === 'interrupted') {
      try { Promise.resolve(audio.ctx.resume()).catch(() => {}); } catch (_) {}
    }
  }

  function rest(delay = 1050) {
    clearTimeout(idleTimer);
    if (!audio || ((active || audience?.live) && !muted)) return;
    idleTimer = setTimeout(() => {
      if (audio && ((!active && !audience?.live) || muted)) {
        try { Promise.resolve(audio.ctx.suspend()).catch(() => {}); } catch (_) {}
      }
    }, delay);
  }

  // Called from a key, tap or click handler. Browsers without Web Audio stay playable.
  function unlock() {
    if (!audio) {
      const Context = window.AudioContext || window.webkitAudioContext;
      const activation = window.navigator && window.navigator.userActivation;
      if (!Context || (activation && !activation.isActive && !activation.hasBeenActive)) return false;
      let ctx;
      try {
        ctx = new Context({latencyHint: 'interactive'});
        audio = audioGraph(ctx);
      } catch (_) {
        if (ctx) { try { Promise.resolve(ctx.close()).catch(() => {}); } catch (_) {} }
        return false;
      }
    }
    audienceArmed = true;
    wake();
    if (!active) rest(1700);
    return true;
  }

  function stopSpeech() {
    if (!spoken) return;
    spoken = null;
    try { window.speechSynthesis.cancel(); } catch (_) {}
  }

  function setMuted(value) {
    muted = Boolean(value);
    if (!audio) return;
    target(audio.master.gain, muted ? 0 : 0.80, audio.ctx.currentTime, 0.016);
    if (muted) {
      target(audio.spinGain.gain, 0, audio.ctx.currentTime, 0.018);
      stopCrowd(); stopSpeech(); silenceShots(); rest(150);
    }
    else { wake(); if (!active) rest(); }
  }

  function idleEngine() {
    active = false;
    lastMix = -1;
    if (audio) {
      const now = audio.ctx.currentTime;
      target(audio.engineBus.gain, 0, now, 0.035);
      target(audio.spinGain.gain, 0, now, 0.018);
      target(audio.scrapeGain.gain, 0, now, 0.016);
      target(audio.scrapeRingGain.gain, 0, now, 0.016);
    }
    rest();
  }

  function stop() {
    audienceArmed = false;
    stopCrowd();
    stopSpeech();
    silenceShots();
    duckUntil = 0;
    marshalUntil = 0;
    idleEngine();
  }

  function update(state = {}) {
    if (!audio) return;
    if (!state.active) {
      // On crossing the finish line, let the flag signal and radio call ring out.
      // An explicit pause or pagehide still cancels every active one-shot.
      if (active) idleEngine();
      return;
    }
    const justStarted = !active;
    if (justStarted) {
      active = true;
      wake();
    }
    if (muted) return;
    const now = audio.ctx.currentTime;
    if (!justStarted && now - lastMix < 0.024) return;
    lastMix = now;
    const rpm = clamp(Number(state.rpm) || 850, 650, 7600);
    const throttle = clamp(Number(state.throttle) || 0, 0, 1);
    const mphFactor = clamp(Math.abs(Number(state.speed) || 0) / 35, 0, 1.4);
    const slip = clamp(Number(state.slide) || 0, 0, 1);
    const rolling = state.airborne ? 0 : Math.min(1, mphFactor);
    const mix = rpm < bases[1] ?
      clamp(Math.log(rpm / bases[0]) / Math.log(bases[1] / bases[0]), 0, 1) :
      1 + clamp(Math.log(rpm / bases[1]) / Math.log(bases[2] / bases[1]), 0, 1);
    const load = 0.53 + throttle * 0.47;
    const duck = now < duckUntil ? 0.57 : 1;
    target(audio.engineBus.gain, duck, now, 0.10);

    for (let i = 0; i < bases.length; i++) {
      const weight = Math.max(0, 1 - Math.abs(mix - i));
      target(audio.layers[i].volume.gain, Math.sqrt(weight) * load * 0.48, now, 0.06);
      target(audio.layers[i].source.playbackRate, clamp(rpm / bases[i], 0.42, 2.9), now, 0.042);
    }

    target(audio.exhaust.frequency, 540 + rpm * 0.15 + 1750 * throttle, now);
    const spool = throttle * clamp((rpm - 1350) / 4700, 0, 1);
    target(audio.gearTone.frequency, 116 + rpm * 0.127, now, 0.085);
    target(audio.driveGain.gain, spool * (0.020 + 0.016 * spool), now, 0.095);
    target(audio.shaftTone.frequency, 34 + rpm / 100, now, 0.05);
    target(audio.shaftGain.gain, throttle * (0.017 + 0.023 * spool), now, 0.065);
    target(audio.intakeVolume.gain, 0.005 + throttle * (0.018 + 0.032 * rpm / 7300), now);
    target(audio.intakeFilter.frequency, 260 + rpm * 0.14, now);
    target(audio.groundVolume.gain, rolling * (0.06 + 0.11 * slip), now);
    target(audio.groundFilter.frequency, 260 + 700 * rolling + 540 * slip, now);
    target(audio.slipVolume.gain, rolling * slip * 0.15, now, 0.035);
    target(audio.slipFilter.frequency, 520 + rolling * 390 + slip * 180, now);

    const spin = state.airborne ? 0 : clamp(Number(state.wheelspin) || 0, 0, 1);
    if (spin > 0) {
      const pitch = 470 + 0.060 * rpm + 210 * spin;
      const flutter = Math.sin(now * 34 + 0.45 * Math.sin(now * 12));
      target(audio.spinBand.frequency, pitch * 1.35, now, 0.046);
      target(audio.spinTone.frequency, pitch * (1 + 0.028 * flutter), now, 0.030);
    }
    target(audio.spinGain.gain, spin * (0.066 + 0.077 * spin), now, spin ? 0.048 : 0.018);

    const rub = clamp(Number(state.rub) || 0, 0, 1);
    let scrape = 0, resonance = 0;
    if (rub > 0) {
      const profile = contactMaterials.get(state.rubMaterial) || contactMaterials.get('rubber');
      const speed = Math.min(1, mphFactor);
      // Stick-slip modulation follows load; banked contacts stay audible even
      // with the player's wheels stopped if another moving vehicle pushes by.
      const flutter = 0.86 + 0.14 * Math.sin(now * 39 + Math.sin(now * 13));
      const pressure = rub * (0.78 + speed * 0.22) * flutter;
      const brightness = 0.73 + 0.40 * rub + 0.22 * speed;
      target(audio.scrapeFilter.frequency, profile.band * brightness, now, 0.035);
      target(audio.scrapeFilter.Q, profile.q, now, 0.035);
      target(audio.scrapeRing.frequency, profile.pitch * (0.81 + 0.25 * rub + 0.15 * speed + 0.045 * flutter), now, 0.034);
      scrape = pressure * profile.noise;
      resonance = pressure * profile.ring;
    }
    target(audio.scrapeGain.gain, scrape, now, rub ? 0.037 : 0.016);
    target(audio.scrapeRingGain.gain, resonance, now, rub ? 0.039 : 0.016);
    if (justStarted) ignition();
  }

  // Track future scheduled notes too. Muting a fanfare must not leave notes
  // pending in a suspended context that could surface on the next unlock.
  function trackShot(sources, nodes, envelope) {
    const cut = () => {
      const now = audio.ctx.currentTime;
      envelope.gain.cancelScheduledValues(now);
      envelope.gain.setTargetAtTime(0.00001, now, 0.004);
      for (const source of sources) source.stop(now + 0.018);
      oneShots.delete(cut);
    };
    oneShots.add(cut);
    sources[0].onended = () => {
      oneShots.delete(cut);
      for (const node of [...sources, ...nodes]) node.disconnect();
    };
  }

  function silenceShots() {
    for (const cut of oneShots) cut();
  }

  // Low-frequency impacts and sweeps share one exponentially decaying envelope.
  function tone(delay, from, to, duration, peak, type = 'sine') {
    const {ctx, master} = audio;
    const when = ctx.currentTime + delay;
    const env = gain(ctx, 0, master);
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(from, when);
    osc.frequency.exponentialRampToValueAtTime(Math.max(12, to), when + duration);
    env.gain.setValueAtTime(0.00001, when);
    env.gain.exponentialRampToValueAtTime(peak, when + Math.min(0.007, duration / 8));
    env.gain.exponentialRampToValueAtTime(0.00002, when + duration);
    osc.connect(env);
    osc.start(when);
    osc.stop(when + duration + 0.012);
    trackShot([osc], [env], env);
  }

  function burst(delay, duration, frequency, q, peak, type = 'lowpass', ventTo = 0) {
    const {ctx, master, noiseBuffer} = audio;
    const when = ctx.currentTime + delay;
    const env = gain(ctx, 0, master);
    const color = filter(ctx, type, frequency, q, env);
    const source = ctx.createBufferSource();
    source.buffer = noiseBuffer;
    source.connect(color);
    env.gain.setValueAtTime(0.00001, when);
    if (ventTo) {
      // Pressure holds the valve open, then the hiss darkens as the air drains.
      color.frequency.setValueAtTime(frequency, when);
      color.frequency.exponentialRampToValueAtTime(ventTo, when + duration);
      env.gain.exponentialRampToValueAtTime(peak, when + duration * 0.07);
      env.gain.linearRampToValueAtTime(peak * 0.70, when + duration * 0.54);
    } else {
      env.gain.exponentialRampToValueAtTime(peak, when + 0.005);
    }
    env.gain.exponentialRampToValueAtTime(0.00002, when + duration);
    source.start(when, random() * 0.85);
    source.stop(when + duration + 0.01);
    trackShot([source], [color, env], env);
  }

  function ignition() {
    burst(0, 0.105, 650, 0.7, 0.13);
    tone(0.03, 74, 42, 0.14, 0.15);
    tone(0.14, 57, 42, 0.12, 0.11);
  }

  // An FM strike opens with metallic sidebands, then settles into a sine tone.
  // Short envelopes give the timing signals a single clear rhythmic edge.
  function fmNote(delay, hz, length, level, brightness = 1.1) {
    const {ctx, master} = audio;
    const when = ctx.currentTime + delay;
    const carrier = ctx.createOscillator();
    const mod = ctx.createOscillator();
    const env = gain(ctx, 0, master);
    const index = gain(ctx, 0, carrier.frequency);
    carrier.frequency.setValueAtTime(hz, when);
    mod.frequency.setValueAtTime(hz * 1.993, when);
    index.gain.setValueAtTime(hz * brightness, when);
    index.gain.exponentialRampToValueAtTime(0.04 * hz, when + length * 0.37);
    env.gain.setValueAtTime(0.00001, when);
    env.gain.exponentialRampToValueAtTime(level, when + 0.005);
    env.gain.exponentialRampToValueAtTime(0.00002, when + length);
    mod.connect(index);
    carrier.connect(env);
    carrier.start(when);
    mod.start(when);
    carrier.stop(when + length + 0.01);
    mod.stop(when + length + 0.01);
    trackShot([carrier, mod], [index, env], env);
  }

  function airHorn(truck) {
    const {ctx, master} = audio;
    const voice = truckHorns[Number.isInteger(truck) ? clamp(truck, 0, truckHorns.length - 1) : 0];
    const now = ctx.currentTime;
    const release = now + voice.duration;
    const env = gain(ctx, 0, master);
    const bell = filter(ctx, 'lowpass', 800, 0.78, env);
    bell.frequency.setValueAtTime(800, now);
    bell.frequency.exponentialRampToValueAtTime(voice.cutoff, now + 0.035);
    bell.frequency.linearRampToValueAtTime(voice.cutoff, release);
    bell.frequency.exponentialRampToValueAtTime(670, release + 0.049);
    env.gain.setValueAtTime(0.00001, now);
    env.gain.linearRampToValueAtTime(0.135, now + 0.023);
    env.gain.linearRampToValueAtTime(0.118, release);
    env.gain.exponentialRampToValueAtTime(0.00002, release + 0.055);

    // The second reed catches a little later as the pressure in the line rises.
    const reeds = voice.bells.map((hz, i) => {
      const reed = ctx.createOscillator();
      const start = now + i * 0.013;
      reed.type = 'sawtooth';
      reed.frequency.setValueAtTime(hz * 0.91, start);
      reed.frequency.exponentialRampToValueAtTime(hz, start + 0.029);
      reed.frequency.linearRampToValueAtTime(hz, release);
      reed.frequency.exponentialRampToValueAtTime(hz * 0.95, release + 0.043);
      reed.connect(bell);
      reed.start(start);
      reed.stop(release + 0.061);
      return reed;
    });
    trackShot(reeds, [bell, env], env);
    burst(0, 0.040, 1800, 0.7, 0.09, 'bandpass');
    burst(voice.duration, 0.052, 1350, 0.65, 0.065, 'bandpass');
  }

  // A buzzy reed opens and closes against the beak's moving vocal resonance.
  // The survey duck answers with a loud first syllable and a shorter echo.
  function quack(delay, pitch, duration, level) {
    const {ctx, master} = audio;
    const start = ctx.currentTime + delay;
    const end = start + duration;
    const env = gain(ctx, 0, master);
    const beak = filter(ctx, 'bandpass', 730, 1.5, env);
    const reed = ctx.createOscillator();
    const flutter = ctx.createOscillator();
    const flutterDepth = gain(ctx, 16, reed.frequency);
    flutter.type = 'square';
    flutter.frequency.value = 38;
    reed.type = 'sawtooth';
    reed.frequency.setValueAtTime(pitch * 0.8, start);
    reed.frequency.exponentialRampToValueAtTime(pitch * 1.18, start + 0.023);
    reed.frequency.exponentialRampToValueAtTime(pitch * 0.65, end);
    beak.frequency.setValueAtTime(730, start);
    beak.frequency.exponentialRampToValueAtTime(1570, start + 0.026);
    beak.frequency.exponentialRampToValueAtTime(590, end);
    env.gain.setValueAtTime(0.00001, start);
    env.gain.linearRampToValueAtTime(level, start + 0.014);
    env.gain.linearRampToValueAtTime(level * 0.77, start + duration * 0.72);
    env.gain.exponentialRampToValueAtTime(0.00002, end);
    flutter.connect(flutterDepth);
    reed.connect(beak);
    reed.start(start);
    flutter.start(start);
    reed.stop(end + 0.008);
    flutter.stop(end + 0.008);
    trackShot([reed, flutter], [flutterDepth, beak, env], env);
  }

  // Two moving formants give a rising pitch a rounded "woo" through the PA.
  function whoop(delay, pitch, duration, level) {
    const {ctx, master} = audio;
    const start = ctx.currentTime + delay;
    const crest = start + duration * 0.42;
    const end = start + duration;
    const env = gain(ctx, 0, master);
    const mouth = filter(ctx, 'bandpass', 410, 1.9, env);
    const throat = filter(ctx, 'bandpass', 960, 3.4, env);
    const voice = ctx.createOscillator();
    voice.type = 'sawtooth';
    voice.frequency.setValueAtTime(pitch, start);
    voice.frequency.exponentialRampToValueAtTime(pitch * 1.63, crest);
    voice.frequency.exponentialRampToValueAtTime(pitch * 1.32, end);
    mouth.frequency.setValueAtTime(410, start);
    mouth.frequency.exponentialRampToValueAtTime(590, crest);
    mouth.frequency.exponentialRampToValueAtTime(385, end);
    throat.frequency.setValueAtTime(960, start);
    throat.frequency.exponentialRampToValueAtTime(1200, crest);
    throat.frequency.exponentialRampToValueAtTime(890, end);
    env.gain.setValueAtTime(0.00001, start);
    env.gain.linearRampToValueAtTime(level, start + 0.028);
    env.gain.linearRampToValueAtTime(level * 0.75, start + duration * 0.69);
    env.gain.exponentialRampToValueAtTime(0.00002, end);
    voice.connect(mouth);
    voice.connect(throat);
    voice.start(start);
    voice.stop(end + 0.008);
    trackShot([voice], [mouth, throat, env], env);
  }

  // The terrace uses its own distance filter, stereo position and short PA-free
  // reflections. Pause, muting and replay seeks can silence its voices alone.
  function buildCrowdBus() {
    const {ctx, master} = audio;
    const level = gain(ctx, 0, master);
    const direction = ctx.createStereoPanner ? ctx.createStereoPanner() : ctx.createGain();
    direction.connect(level);
    const front = filter(ctx, 'lowpass', 3600, .61, direction);
    const slap = ctx.createDelay ? ctx.createDelay(.35) : null;
    if(slap){
      const backWall = filter(ctx, 'lowpass', 1900, .56, gain(ctx, .14, front));
      slap.delayTime.value = .113;slap.connect(backWall);
    }
    const rustle = gain(ctx, 0, front);
    audio.grit.connect(filter(ctx, 'bandpass', 930, .69, rustle));
    return {ctx, level, direction, front, slap, rustle, cache:new Map(), voices:new Map(),
      clock:-Infinity, reaction:-Infinity, heat:0, live:false, lastMix:-Infinity};
  }

  // Separate, repeatable noise streams keep crowd rhythm independent of the V8
  // and impact sounds. The same run of the replay finds the same terrace calls.
  function seatNoise(index, salt) {
    let n = Math.imul(index | 0, 0x9e3779b1) ^ Math.imul(salt | 0, 0x85ebca6b);
    n = Math.imul(n ^ (n >>> 16), 0x7feb352d);
    n = Math.imul(n ^ (n >>> 15), 0x846ca68b);
    return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
  }

  // Original terrace cues, packed as 4-bit IMA ADPCM per channel. The
  // five chants were voiced offline with CMU Flite (SLT, AWB and RMS). For the
  // nine wordless calls we drove changing oo/oh/ah/eh/ee formants with a
  // glottal pulse, breath noise and a swept fundamental in three registers.
  // The whistles are lip glides, handclaps are clusters of noise impulses,
  // and bottle clinks are decaying inharmonic glass modes. The four stereo
  // babble stems overlap 18 independent voices; they are recombined live.
  // Prebaking these takes keeps speech synthesis off the rendering thread.
  const terraceClips = {
    send: [14000,1,6264,''],
    lap: [14000,1,13257,''],
    move: [14000,1,7495,''],
    numbers: [14000,1,23412,''],
    truck: [14000,1,17184,''],
    hoot0: [18000,1,12352,''],
    hoot1: [18000,1,13535,''],
    hoot2: [18000,1,14717,''],
    holler0: [18000,1,8291,''],
    holler1: [18000,1,9085,''],
    holler2: [18000,1,9879,''],
    yeehaw0: [18000,1,16413,''],
    yeehaw1: [18000,1,17984,''],
    yeehaw2: [18000,1,19556,''],
    whistle0: [18000,1,12511,''],
    whistle1: [18000,1,13140,''],
    whistle2: [18000,1,13770,''],
    clap0: [18000,1,1890,''],
    clap1: [18000,1,1890,''],
    clap2: [18000,1,1890,''],
    glass0: [18000,1,7200,''],
    glass1: [18000,1,7200,''],
    glass2: [18000,1,7200,''],
    babble0: [14000,2,24360,''],
    babble1: [14000,2,24360,''],
    babble2: [14000,2,24360,''],
    babble3: [14000,2,24360,'']
  };
  const chantNames = ['send','lap','move','numbers','truck'];
  const stepSize=[7,8,9,10,11,12,13,14,16,17,19,21,23,25,28,31,34,37,41,45,50,55,
    60,66,73,80,88,97,107,118,130,143,157,173,190,209,230,253,279,307,337,371,408,449,
    494,544,598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,1878,2066,2272,2499,2749,
    3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,10442,11487,12635,
    13899,15289,16818,18500,20350,22385,24623,27086,29794,32767];
  const stepDelta=new Int32Array(stepSize.length*16),nextStep=new Uint16Array(stepDelta.length);
  for(let s=0;s<stepSize.length;s++)for(let n=0;n<16;n++){
    const step=stepSize[s],slot=s*16+n;
    const amp=(step>>3)+((n&4)?step:0)+((n&2)?step>>1:0)+((n&1)?step>>2:0);
    stepDelta[slot]=(n&8)?-amp:amp;
    nextStep[slot]=clamp(s+[-1,-1,-1,-1,2,4,6,8][n&7],0,88)*16;
  }

  // Decode each short clip only at first use. An independent predictor for
  // each ear keeps the bleachers wide when the player looks along the stands.
  function crowdSample(house,kind,variant){
    const key=terraceClips[kind]?kind:kind+variant;
    if(house.cache.has(key))return house.cache.get(key);
    const [rate,channels,frames,encoded]=terraceClips[key];
    const bytes=atob(encoded),clip=house.ctx.createBuffer(channels,frames,rate);
    // These three short noise transients retain their leading hand slap in PCM.
    if(kind==='clap'){
      const out=clip.getChannelData(0);
      for(let i=0;i<frames;i++)out[i]=(bytes.charCodeAt(i)-128)/127;
      house.cache.set(key,clip);return clip;
    }
    const stride=4+Math.ceil((frames-1)/2);
    for(let c=0;c<channels;c++){
      const out=clip.getChannelData(c),base=c*stride;
      let sample=(bytes.charCodeAt(base)|(bytes.charCodeAt(base+1)<<8))<<16>>16;
      let step=bytes.charCodeAt(base+2)<<4,source=base+4;
      out[0]=sample/32768;
      for(let i=1;i<frames;i++){
        const packed=bytes.charCodeAt(source);
        const token=step|((i&1)?(packed&15):(packed>>4));
        if(!(i&1))source++;
        sample+=stepDelta[token];
        sample=sample < -32768 ? -32768 : sample > 32767 ? 32767 : sample;
        step=nextStep[token];out[i]=sample/32768;
      }
    }
    house.cache.set(key,clip);return clip;
  }

  function seatedVoice(house,kind,variant,delay,rate,volume,seat=0) {
    if(house.voices.size>=24)return;
    const {ctx}=house, source=ctx.createBufferSource(), voice=ctx.createGain();
    source.buffer=crowdSample(house,kind,variant);
    const start=ctx.currentTime+delay;
    voice.gain.value=volume;source.playbackRate.value=rate;source.connect(voice);
    const pan=ctx.createStereoPanner && Math.abs(seat)>.01 ? ctx.createStereoPanner() : null;
    if(pan){pan.pan.value=seat;voice.connect(pan);}
    const sound=pan||voice;sound.connect(house.front);if(house.slap)sound.connect(house.slap);
    source.onended=()=>{
      house.voices.delete(source);source.disconnect();voice.disconnect();if(pan)pan.disconnect();
    };
    house.voices.set(source,voice);source.start(start);
  }

  function silenceTerrace(house) {
    const now=house.ctx.currentTime;
    for(const [source,voice] of house.voices){
      voice.gain.cancelScheduledValues(now);voice.gain.setTargetAtTime(0,now,.006);
      try{source.stop(now+.024);}catch(_){}
    }
    // onended owns the disconnects, including calls cancelled before their onset.
    house.voices.clear();
  }

  function stopCrowd() {
    const house=audience;if(!house?.live)return;
    silenceTerrace(house);house.live=false;house.clock=house.reaction=house.lastMix=-Infinity;house.heat=0;
    target(house.level.gain,0,house.ctx.currentTime,.016);
  }

  function rallyCall(house,index,intensity,group=false) {
    const r=seatNoise(index,152), side=(seatNoise(index,165)-.5)*.90, variant=Math.floor(r*3);
    const name=group?chantNames[Math.floor(seatNoise(index,188)*chantNames.length)]:
      ['hoot','holler','yeehaw','send','move','lap','holler','hoot'][Math.floor(seatNoise(index,156)*8)];
    // One row calls. Another joins late with a different throat and register.
    seatedVoice(house,name,variant,0,.93+.15*r,intensity*.28,side);
    if(group||r>.43){
      const answer=group?name:r>.73?'yeehaw':'hoot', delay=group?.045+.055*r:.27+.19*r;
      seatedVoice(house,answer,(variant+1)%3,delay,group?1.045+.06*r:.89+.08*r,intensity*.19,-side);
      if(group)seatedVoice(house,name,0,.11+.03*r,.9+.06*r,intensity*.1,-side*.57);
    }
  }

  function answerCrowd(house,clock,energy) {
    if(clock-house.reaction<.88)return;
    house.reaction=clock;
    const index=Math.floor(clock*3.2)+61,v=index%3;
    rallyCall(house,index,.8+.24*energy,true);
    seatedVoice(house,'hoot',(v+1)%3,.10,1.02,.17,.32);
    seatedVoice(house,'whistle',v,.27+.15*energy,.97,.083,-.38);
    seatedVoice(house,'clap',v,.06,1.02,.13,-.21);
    seatedVoice(house,'clap',(v+1)%3,.228,.93,.11,.30);
    seatedVoice(house,'glass',v,.42+.17*seatNoise(index,86),1,.072,.23);
  }

  // Drive this once per displayed racing or tour frame. Timed sound events are
  // located on the game clock; their short internal rhythms run on the audio
  // clock so uneven animation frame pacing does not stagger a row's chant.
  function crowd(level,pan,clock,energy=0) {
    if(!audio||!audienceArmed||muted||document.hidden||!Number.isFinite(clock))return;
    level=clamp(Number(level)||0,0,1);pan=clamp(Number(pan)||0,-1,1);energy=clamp(Number(energy)||0,0,1);
    if(level<.012){
      if(audience?.live){stopCrowd();if(!active)rest();}
      return;
    }
    if(!audience)audience=buildCrowdBus();
    const house=audience,now=house.ctx.currentTime,
      seek=Number.isFinite(house.clock)&&(clock<house.clock-.002||clock-house.clock>.85);
    if(!house.live||seek){
      if(seek)silenceTerrace(house);
      house.reaction=-Infinity;house.lastMix=-Infinity;house.heat=0;house.clock=clock-.06;house.live=true;wake();
      // Opening the very first frame on a live corner should already have a crowd.
      seatedVoice(house,'babble',Math.abs(Math.floor(clock*.7))%4,0,1,.125);
    }
    if(now-house.lastMix<.031 && energy<=house.heat+.18)return;
    house.lastMix=now;
    // Near/far timbre and stereo position follow the stand continuously, with
    // reserved headroom for the marshal's lights, the horn and the race radio.
    const duck=now<marshalUntil?.44:now<duckUntil?.58:1;
    target(house.level.gain,Math.round(level*(.80+.13*energy)*duck*200)/200,now,.085);
    target(house.front.frequency,Math.round((1100+3650*level)/30)*30,now,.085);
    target(house.rustle.gain,.040+.010*Math.sin(clock*1.7+.53*Math.sin(clock*.74)),now,.15);
    if(house.direction.pan)target(house.direction.pan,Math.round(pan*70)/100,now,.075);
    const from=house.clock;
    // Each lane has its own human-sized spacing and jitter; just one event can
    // fall in a normal frame on each lane, even when recovering from a slow frame.
    function due(period,salt,spread,play){
      const first=Math.max(0,Math.floor((from-spread)/period));
      const last=Math.floor(clock/period);
      for(let i=first;i<=last;i++){
        const t=i*period+.09+spread*seatNoise(i,salt);
        if(t>from&&t<=clock)play(i);
      }
    }
    due(1.13,24,.16,i=>seatedVoice(house,'babble',Math.floor(seatNoise(i,18)*4),0,.93+.13*seatNoise(i,19),.12));
    due(2.37,8,.91,i=>{if(level>.095)rallyCall(house,i,.86, i%5===2);});
    due(.81,45,.57,i=>{
      if(level<.12)return;
      const r=seatNoise(i,54),variant=i%3,side=seatNoise(i,61)-.5;
      if(r<.20){seatedVoice(house,'whistle',variant,0,.91+.19*r,.075,side);return;}
      if(r<.41){seatedVoice(house,'glass',variant,0,.91+.24*r,.092,side);return;}
      seatedVoice(house,'clap',variant,0,.86+.27*r,.13,side);
      seatedVoice(house,'clap',(variant+2)%3,.14+.09*seatNoise(i,44),1.08,.115,side+.12);
    });
    if(energy>.36 && (house.heat<.29||energy-house.heat>.22))answerCrowd(house,clock,energy);
    house.heat=energy;house.clock=clock;
  }

  // Separate the mortar cough, initial pressure impulse, reflected boom and
  // late glitter. Distance dulls high frequencies and reduces direct energy.
  function fireworksSound(cue){
    if(!cue)return;
    const {kind,delay,seed,distance,venue}=cue,tag=Math.round(seed*93);
    const jitter=n=>seatNoise(tag,n),gain=Math.min(1.28,78/(44+distance));
    const brightness=1/(1+distance*.0025);
    if(cue.lift){
      tone(delay,115+22*jitter(3),49,.11,.082*gain,'sine');
      burst(delay,.098,650+300*jitter(4),.64,.17*gain,'lowpass',235);
      if(kind==='ring'||kind==='split')tone(delay+.07,740+170*jitter(7),1330+150*jitter(8),.58,.023*gain,'triangle');
      else burst(delay+.06,.27,1980*brightness,.88,.048*gain,'bandpass',730);
      return;
    }
    const depth={willow:.98,palm:.89,peony:.80,split:.62,ring:.57,crackle:.67}[kind]||.75;
    const direct=gain*(.75+depth*.25),bass=64+48*(1-depth)+13*jitter(12);
    burst(delay,.066,3900*brightness,.62,.42*direct,'lowpass',600);
    tone(delay+.009,bass,28+9*jitter(13),.38+depth*.23,.205*direct,'sine');
    burst(delay+.018,.27+depth*.20,860*brightness,.64,.26*direct,'lowpass',125);
    // Desert walls answer later than steel grandstands. Reflections are
    // softer and darker on each pass through the arena.
    const reflection=venue==='arizona'?.33:venue==='indiana'?.095:.185;
    for(let i=0;i<2;i++){
      const echo=delay+reflection*(1+i*1.73)+jitter(17+i)*.038;
      burst(echo,.19+.14*i,660/(1+i*.8),.7,direct*(i?.055:.14),'lowpass',160);
    }
    if(kind==='split'){
      for(let i=0;i<4;i++)burst(delay+.8+i*.052+jitter(22+i)*.04,.075,2550*brightness,.63,.145*direct,'highpass');
    }else if(kind==='crackle'||kind==='willow'||kind==='palm'){
      const count=kind==='crackle'?16:kind==='palm'?6:9;
      for(let i=0;i<count;i++){
        const at=(kind==='crackle'?.91:.45)+1.17*jitter(32+i),pitch=(2100+3300*jitter(52+i))*brightness;
        burst(delay+at,.028+.05*jitter(72+i),pitch,.8,direct*(kind==='crackle'?.19:.085)*(.55+.45*jitter(i)),'bandpass');
      }
    }
  }

  function effect(kind, variant) {
    if (!audio || muted) return;
    const now = audio.ctx.currentTime;
    let cooldown = ['land', 'crush', 'hit', 'prop'].includes(kind) ? 0.17 : 0.055;
    if (longCues.has(kind)) cooldown = 0.42;
    if (kind!=='firework' && now - (recentEffects.get(kind) ?? -2) < cooldown && audio.ctx.state === 'running') return;
    recentEffects.set(kind, now);
    wake();
    if (kind === 'tick' || kind === 'go') marshalUntil = now + (kind === 'go' ? .48 : .23);
    switch (kind) {
      case 'horn':
        airHorn(variant);
        break;
      case 'brass':
        // A low two-note tuba answer. Opening the bell filter brings the
        // harmonics in after the lip buzz, then they darken with the release.
        for(const [delay,hz,duration] of [[0,103.83,.21],[.24,77.78,.45]]){
          const {ctx,master}=audio,start=ctx.currentTime+delay,end=start+duration;
          const env=gain(ctx,0,master),bell=filter(ctx,'lowpass',310,1.4,env),lip=ctx.createOscillator();
          lip.type='sawtooth';lip.frequency.setValueAtTime(hz*.78,start);lip.frequency.exponentialRampToValueAtTime(hz,start+.045);
          bell.frequency.setValueAtTime(240,start);bell.frequency.exponentialRampToValueAtTime(870,start+.065);bell.frequency.exponentialRampToValueAtTime(260,end);
          env.gain.setValueAtTime(.00001,start);env.gain.linearRampToValueAtTime(.16,start+.035);env.gain.linearRampToValueAtTime(.115,start+duration*.70);env.gain.exponentialRampToValueAtTime(.00002,end);
          lip.connect(bell);lip.start(start);lip.stop(end+.015);trackShot([lip],[bell,env],env);
        }
        break;
      case 'copier':
        for(const [delay,hz] of [[0,286],[.14,412],[.29,232]]){
          tone(delay,hz,hz*.52,.095,.060,'triangle');burst(delay+.02,.11,3500,1.45,.085,'bandpass',780);
        }
        break;
      case 'coin':
        for(const [i,hz] of [1245,1661,2093].entries())fmNote(i*.062,hz,.22,.065,1.9);
        break;
      case 'quack':
        quack(0, 255, 0.148, 0.35);
        quack(0.195, 220, 0.117, 0.27);
        break;
      case 'bell':
        // The clapper excites three inharmonic partials with different decays.
        tone(0, 828, 820, 0.56, 0.155);
        tone(0.002, 1975, 1960, 0.27, 0.080);
        tone(0.003, 2818, 2800, 0.15, 0.043);
        burst(0, 0.030, 3100, 1.1, 0.10, 'bandpass');
        break;
      case 'bleep':
        tone(0, 525, 655, 0.073, 0.074, 'square');
        tone(0.071, 868, 610, 0.081, 0.068, 'square');
        fmNote(0.175, ident[1] * 3, 0.14, 0.103, 1.7);
        break;
      case 'steam':
        tone(0, 156, 87, 0.067, 0.10, 'triangle');
        burst(0.014, 0.41, 3250, 0.85, 0.26, 'bandpass', 880);
        tone(0.069, 1580, 735, 0.24, 0.047);
        break;
      case 'cheer':
        whoop(0, 203, 0.32, 0.20);
        whoop(0.063, 251, 0.29, 0.14);
        burst(0.213, 0.060, 1620, 0.95, 0.20, 'bandpass');
        burst(0.292, 0.053, 1950, 0.85, 0.15, 'bandpass');
        break;
      case 'firework':
        fireworksSound(variant);break;
      case 'holler':
        if (audience?.live) answerCrowd(audience, audience.clock, 1);
        break;
      case 'select':
        fmNote(0, ident[0], 0.080, 0.072, 1.6);
        break;
      case 'tick':
        tone(0, 86, 54, 0.095, 0.10);
        fmNote(0, ident[1], 0.14, 0.15, 0.75);
        break;
      case 'go':
        tone(0, 108, 48, 0.26, 0.19);
        fmNote(0, ident[0], 0.15, 0.14);
        fmNote(0.075, ident[2], 0.14, 0.14);
        fmNote(0.15, ident[3] * 2, 0.30, 0.13);
        break;
      case 'launchPerfect':
        // A high glassy answer leaves space under it for the green-light signal.
        fmNote(0.025, ident[0] * 3, 0.12, 0.10, 0.9);
        fmNote(0.089, ident[2] * 3, 0.13, 0.10, 0.8);
        fmNote(0.175, ident[3] * 3, 0.27, 0.12, 0.6);
        break;
      case 'launchBog':
        // Two uneven exhaust coughs and a weaker pop from the other bank.
        tone(0, 143, 59, 0.10, 0.16, 'triangle');
        burst(0.004, 0.079, 490, 1.10, 0.29, 'bandpass');
        tone(0.081, 110, 45, 0.12, 0.13, 'triangle');
        burst(0.087, 0.078, 360, 0.85, 0.25, 'bandpass');
        tone(0.205, 81, 39, 0.10, 0.08);
        break;
      case 'checkpoint':
        fmNote(0, ident[0] * 2, 0.12, 0.11, 0.8);
        fmNote(0.075, ident[2] * 2, 0.20, 0.10, 0.55);
        break;
      case 'lap':
        fmNote(0, ident[1], 0.14, 0.14);
        fmNote(0.075, ident[1] * 2, 0.13, 0.095);
        fmNote(0.195, ident[3] * 2, 0.28, 0.12, 0.8);
        break;
      case 'finish':
        tone(0, 101, 46, 0.28, 0.17);
        ident.forEach((hz, i) => fmNote(i * 0.091, hz, 0.22, 0.14));
        fmNote(0.43, ident[3] * 2, 0.46, 0.13, 0.8);
        break;
      case 'recover':
        fmNote(0, ident[2] * 2, 0.15, 0.09, 1.7);
        fmNote(0.075, ident[2], 0.17, 0.10, 1.3);
        fmNote(0.22, ident[0], 0.19, 0.11, 0.7);
        break;
      case 'shift':
        // Linkage click followed by the dog ring seating in the next gear.
        burst(0, 0.040, 1750, 1.3, 0.24, 'bandpass');
        tone(0.027, 153, 69, 0.105, 0.14, 'triangle');
        break;
      case 'prop': {
        const profile = contactMaterials.get(variant) || contactMaterials.get('wood');
        burst(0, 0.084, profile.band * 1.6, 0.75, 0.35, 'bandpass');
        tone(0.015, 119, 52, 0.13, 0.12);
        burst(0.054, 0.105, profile.band * 0.86, 1.15, 0.23, 'bandpass');
        tone(0.075, profile.pitch * 1.4, profile.pitch, 0.13, 0.065, 'triangle');
        break;
      }
      case 'land':
        tone(0, 101, 39, 0.20, 0.25);
        burst(0, 0.19, 600, 0.70, 0.40);
        burst(0.065, 0.13, 1350, 0.70, 0.12);
        break;
      case 'crush':
        tone(0, 123, 44, 0.23, 0.20);
        for (let i = 0; i < 4; i++) {
          burst(i * 0.049, 0.13 + i * 0.025, 680 + random() * 1250, 1.7, 0.50 - i * 0.065, 'bandpass');
        }
        break;
      case 'hit':
        tone(0, 140, 43, 0.18, 0.22);
        burst(0, 0.22, 1250, 0.9, 0.42);
        break;
    }
    if (!active) rest(1350);
  }

  // Restrict speech to an installed English voice. A short radio squelch also
  // works offline when the browser has no local voice or forbids synthesis.
  function call(text) {
    if (!audio || muted || !text) return;
    wake();
    burst(0, 0.075, 1640, 1.15, 0.09, 'bandpass');
    try {
      const synth = window.speechSynthesis;
      const Voice = window.SpeechSynthesisUtterance;
      const voices = synth && synth.getVoices().filter(v => v.localService && /^en(?:[-_]|$)/i.test(v.lang));
      if (Voice && voices && voices.length) {
        stopSpeech();
        const line = new Voice(String(text).slice(0, 125));
        line.voice = voices.find(v => /^en[-_]US$/i.test(v.lang)) || voices[0];
        line.lang = line.voice.lang;
        line.rate = 1.09;
        line.pitch = 0.88;
        line.volume = 0.48;
        spoken = line;
        duckUntil = audio.ctx.currentTime + Math.min(4, line.text.length * 0.064 + 0.3);
        line.onend = line.onerror = () => {
          if (spoken === line) { spoken = null; duckUntil = 0; }
        };
        synth.speak(line);
      }
    } catch (_) { spoken = null; duckUntil = 0; }
    if (!active) rest(1350);
  }

  // An unfocused or backgrounded window should release the audio device.
  window.addEventListener('pagehide', stop);
  document.addEventListener('visibilitychange', () => { if (document.hidden) stop(); });
  return {unlock, setMuted, update, effect, call, crowd, stop};
})();

export {MTMAudio};
